// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {
    AccessControlEnumerable
} from "@openzeppelin/contracts/access/extensions/AccessControlEnumerable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { Roles } from "../access/Roles.sol";

interface ISubAccountFactory {
    function isSubAccount(address account) external view returns (bool);
}

/// @title Treasury
/// @notice **唯一资金池**:储备金存放、空投发出、派付发出、下注收入、回收收入。
///
/// @dev 与被它取代的 `HSKLedger` 的根本差别:那里 `credit()` 只是 `_balance[addr] += amount`
///      ——凭空加数字;这里每一次发放都是**真实 HSK 转账**,金库真的会没钱。由此带来两条
///      记账时代不存在的约束:
///
///      1. **幂等保护的是真金**。重发的空投若不挡住,就是双倍的真实付出(不是数字翻倍)。
///         故 `used[idemKey]` 与 `HSKLedger` 同款,但后果严重得多。
///      2. **余额不足是真实失败路径**,必须显式 revert 而非静默截断。后端据此区分"该告警
///         补充储备金"与"可重试的瞬时故障"——无限重试一笔金库没钱的发放毫无意义。
///
///      **金库与"市场托管"合并为一个**:平台是对手方(结算奖池由平台承担),下注资金与平台
///      自有资金在经济上本就不分离,拆两个池子只增加复杂度。若合规要求资金隔离(破产隔离),
///      需另拆 Escrow——那是合规决策,不是技术决策。
///
///      资金**流出**只有三条路,各自限定角色:`fund`(活动服务/空投)、`payout`(仅 Market
///      合约/卖出与结算派付)、`withdrawReserve`(仅 admin/平台取回储备金)。资金**流入**
///      无需授权(`receive`),下注、回收、充值都是转进来。
contract Treasury is AccessControlEnumerable, ReentrancyGuard, Pausable {
    /// @notice 幂等键 => 是否已处理。防重复发放(真金)。
    ///
    /// @dev **键是加过域前缀的**,不是调用方传进来的原值——查它请用 `fundUsed` / `payoutUsed`,
    ///      或自己算 `keccak256(abi.encode(DOMAIN, idemKey))`。原因见 `_domain`。
    mapping(bytes32 => bool) public used;

    /// @dev 幂等键的**域**。两条发放路径各占一个命名空间。
    ///
    ///      不分域时:`fund` 的键由调用方任意指定,而派付的键是 `PredictionMarket` 按
    ///      `keccak256(abi.encode("SETTLE", eventId, subAccount, outcome))` 算的——三个入参
    ///      全在链上,谁都能提前算出来。于是持 `ACTIVITY_SERVICE_ROLE` 的热钥匙只要用那个键
    ///      **零金额**空投一笔(不花一分钱),就把它烧掉了;等真到结算,`_pay` 撞 "idem used"
    ///      revert,整批结算永远做不成。
    ///
    ///      这条比"清库"更难收拾:`used` 只置不清,换钥匙也救不回来,那笔赢利**永久无法上链派付**。
    ///      分域之后两边各写各的表,任何一个角色都碰不到另一边的键。
    ///      对称地给 payout 也加域:今天 `MARKET_ROLE` 只有市场合约持有、键由合约自己算,
    ///      但那是"当前恰好安全",不是机制保证——留一半不分域,下一个持有该角色的合约就得
    ///      重新论证一遍。
    bytes32 private constant DOMAIN_FUND = keccak256("TREASURY_IDEM_FUND");
    bytes32 private constant DOMAIN_PAYOUT = keccak256("TREASURY_IDEM_PAYOUT");

    /// @notice 子账户工厂。**用于校验收款方**:发放只能打进工厂签发的子账户,
    ///         不能打到任意地址。为空 = 不校验(兼容未接工厂的旧部署)。
    address public factory;
    /// @notice 单笔发放上限(`fund`)。0 = 不限。
    ///         **只有冷钱包 admin 能改**——热钥匙若能自己调高上限,这道限制就没有意义。
    uint256 public fundLimit;

    /// @notice 单次批量入口最多几条（第二次审计 #5：过大的批次会因 gas 不够整笔失败,
    ///         且失败形态是 out-of-gas 回滚,重试永远是同一批、永远失败)。
    /// @dev 200 比后端现行分块(`PM_CHAIN_SUBMIT_BATCH_MAX=20`)大一个数量级,又远低于
    ///      任何一条链的区块 gas 上限。它不是"最优批量",是让**不可能提交无界批次**
    ///      这件事由合约保证,而不是由一个环境变量保证。
    uint256 public constant MAX_BATCH = 200;

    /// @notice 累计发出 / 累计收到 / 累计取回,供 O(1) 审计与储备金监控。
    /// @dev 恒等式:
    ///      `address(this).balance == 初始注资 + totalReceived - totalPaid - totalWithdrawn`。
    ///      `totalReceived` 只统计经 `receive`/`depositReserve` 进来的,构造时直接给的不计入。
    ///
    ///      **取款单独计而不并入 `totalPaid`**:后者的口径是「业务发放」(空投/派付),
    ///      把管理员取回储备金算进去会让「一共发了多少奖励」这个指标虚高。两类出账的
    ///      审计意义完全不同,合并之后就再也拆不开了。
    uint256 public totalPaid;
    uint256 public totalReceived;
    uint256 public totalWithdrawn;

    event ReserveReceived(address indexed from, uint256 amount);
    event ReserveDeposited(address indexed from, uint256 amount, bytes32 indexed memo);
    event Funded(address indexed subAccount, uint256 amount, bytes32 reason, bytes32 idemKey);
    event PaidOut(address indexed subAccount, uint256 amount, bytes32 reason, bytes32 idemKey);
    event ReserveWithdrawn(address indexed to, uint256 amount);
    event FactorySet(address indexed factory);
    event FundLimitSet(uint256 limit);

    constructor(address admin) {
        require(admin != address(0), "zero admin");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
    }

    /// @notice 绑定子账户工厂。设了之后 `fund`/`payout` 的收款方必须是已登记的子账户。
    function setFactory(address newFactory) external onlyRole(DEFAULT_ADMIN_ROLE) {
        factory = newFactory;
        emit FactorySet(newFactory);
    }

    /// @notice 一键冻结所有出金（第二次审计：「系统也没有紧急暂停开关」）。
    ///
    /// @dev **闸只装在这一处**：钱离开系统只有金库这一个出口——`fund`/`batchFund` 是
    ///      空投，`payout`/`batchPayout` 是卖出回款、结算派付与销毁退款。盘口那边
    ///      `confirmTransfer`/`confirmMerge`/`batchSettle` 全要调 `payout`，堵住这里
    ///      每一条把钱送出去的路都断了；`confirmMatch` 只把钱收进来，继续可用也拿不走
    ///      一分钱。给每个合约各装一个开关反而制造「半停」状态，那正是最难判断的处境。
    ///
    ///      **入金不挡**（`depositReserve` / `receive`）：停机是防钱流出去，
    ///      不是把用户的钱挡在门外。**`withdrawReserve` 也不挡**：它只有多签能调，
    ///      热钥匙泄露碰不到；停机时把钱撤走恰恰是应急手段之一，堵上等于自断退路。
    function pause() external onlyRole(Roles.PAUSER_ROLE) {
        _pause();
    }

    /// @notice 解冻。**只有多签能解**——这是热钥匙敢做成单签的全部理由。
    ///
    /// @dev 停与解不对称：`PAUSER_ROLE` 只能停不能放，泄露了最坏也只是拒绝服务；
    ///      同一把钥匙能停能解的话，拿到它的人可以「停 → 勒索 → 解」、反复扰动。
    ///      代价是误停之后要等多签流程恢复，这是明知并接受的。
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /// @notice 设置单笔发放上限。0 = 不限。
    function setFundLimit(uint256 limit) external onlyRole(DEFAULT_ADMIN_ROLE) {
        fundLimit = limit;
        emit FundLimitSet(limit);
    }

    /// @dev 收款方校验:未绑定工厂时放行(兼容旧部署),绑定后必须是已登记的子账户。
    function _requireSubAccount(address to) internal view {
        if (factory != address(0)) {
            require(ISubAccountFactory(factory).isSubAccount(to), "not a sub account");
        }
    }

    /// @notice 收款兜底:用户下注、活动结束回收都走这里(子账户直接转入)。无需授权。
    receive() external payable {
        totalReceived += msg.value;
        emit ReserveReceived(msg.sender, msg.value);
    }

    /// @notice **储备金充值入口**。项目方注资走这个函数而不是直接转账,好处有二:
    ///         (1) 调用方拿到明确的函数名与 `memo`,不必"往某个地址裸转"这种容易出错的操作;
    ///         (2) 事件与下注/回收的入账区分开——三者都会增加金库余额,但会计口径完全不同,
    ///             靠 `from` 反推需要链下维护子账户名单,不如发不同的事件干净。
    ///         `memo` 供注资方标注批次/来源,链上留痕,不参与任何逻辑。
    function depositReserve(bytes32 memo) external payable {
        require(msg.value > 0, "zero deposit");
        totalReceived += msg.value;
        emit ReserveDeposited(msg.sender, msg.value, memo);
    }

    /// @notice 空投 / 任务奖励:金库 → 子账户。
    function fund(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        require(fundLimit == 0 || amount <= fundLimit, "exceeds fund limit");
        _pay(subAccount, amount, _domain(DOMAIN_FUND, idemKey));
        emit Funded(subAccount, amount, reason, idemKey);
    }

    /// @notice 批量空投(对齐后端组批上链);每笔独立幂等,任一失败整批回滚。
    function batchFund(
        address[] calldata subAccount,
        uint256[] calldata amount,
        bytes32[] calldata reason,
        bytes32[] calldata idemKey
    ) external onlyRole(Roles.ACTIVITY_SERVICE_ROLE) nonReentrant whenNotPaused {
        require(
            subAccount.length == amount.length && amount.length == reason.length
                && reason.length == idemKey.length,
            "length mismatch"
        );
        require(subAccount.length <= MAX_BATCH, "batch too large");
        for (uint256 i = 0; i < subAccount.length; i++) {
            _requireSubAccount(subAccount[i]);
            require(fundLimit == 0 || amount[i] <= fundLimit, "exceeds fund limit");
            _pay(subAccount[i], amount[i], _domain(DOMAIN_FUND, idemKey[i]));
            emit Funded(subAccount[i], amount[i], reason[i], idemKey[i]);
        }
    }

    /// @notice 卖出回款 / 结算派付:金库 → 子账户。
    /// @dev 收敛到 `MARKET_ROLE`(仅 `PredictionMarket` 合约持有):派付必须经过市场的胜负
    ///      判定,活动服务不能绕过市场直接给人发钱。
    function payout(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey)
        external
        onlyRole(Roles.MARKET_ROLE)
        nonReentrant
        whenNotPaused
    {
        _requireSubAccount(subAccount);
        _pay(subAccount, amount, _domain(DOMAIN_PAYOUT, idemKey));
        emit PaidOut(subAccount, amount, reason, idemKey);
    }

    /// @notice 批量派付(结算逐仓)。`amount == 0` 的条目只消费幂等键、不转账——正常结算
    ///         批次里赢家与输家(payout=0)混在一起,零派付不应导致整批失败。
    function batchPayout(
        address[] calldata subAccount,
        uint256[] calldata amount,
        bytes32[] calldata reason,
        bytes32[] calldata idemKey
    ) external onlyRole(Roles.MARKET_ROLE) nonReentrant whenNotPaused {
        require(
            subAccount.length == amount.length && amount.length == reason.length
                && reason.length == idemKey.length,
            "length mismatch"
        );
        require(subAccount.length <= MAX_BATCH, "batch too large");
        for (uint256 i = 0; i < subAccount.length; i++) {
            if (amount[i] > 0) {
                _requireSubAccount(subAccount[i]);
                _pay(subAccount[i], amount[i], _domain(DOMAIN_PAYOUT, idemKey[i]));
            } else {
                // 零金额也必须消费幂等键,否则同一个键可无限重放(污染链下对账),
                // 且该键之后还能被拿来派付真金——幂等保护形同虚设。
                // **域要和上面那支一致**:两支写不同的表等于零派付根本没占住这个键。
                bytes32 k = _domain(DOMAIN_PAYOUT, idemKey[i]);
                require(!used[k], "idem used");
                used[k] = true;
            }
            emit PaidOut(subAccount[i], amount[i], reason[i], idemKey[i]);
        }
    }

    /// @notice 平台取回储备金(活动结束结余)。
    function withdrawReserve(address to, uint256 amount)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
        nonReentrant
    {
        require(to != address(0), "zero to");
        require(address(this).balance >= amount, "insufficient treasury");
        totalWithdrawn += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
        emit ReserveWithdrawn(to, amount);
    }

    /// @notice 某个**空投**幂等键是否已用过。链下对账查这个,别直接读 `used`。
    function fundUsed(bytes32 idemKey) external view returns (bool) {
        return used[_domain(DOMAIN_FUND, idemKey)];
    }

    /// @notice 某个**派付**幂等键是否已用过。
    function payoutUsed(bytes32 idemKey) external view returns (bool) {
        return used[_domain(DOMAIN_PAYOUT, idemKey)];
    }

    /// @dev 给幂等键加域前缀。定长两段 `abi.encode`,不存在拼接歧义。
    function _domain(bytes32 domain, bytes32 idemKey) private pure returns (bytes32) {
        return keccak256(abi.encode(domain, idemKey));
    }

    /// @dev 发放共同路径:幂等 → 余额校验 → 真实转账 → 累计器。
    ///      **`idemKey` 传进来时必须已经加过域**(见 `_domain`)——这个函数不认原始键。
    ///      **先置幂等标记再转账**(checks-effects-interactions),配合 `nonReentrant`
    ///      双重防重入——收款方若是合约,其 `receive` 可能回调进来。
    function _pay(address to, uint256 amount, bytes32 idemKey) internal {
        require(to != address(0), "zero to");
        require(!used[idemKey], "idem used");
        require(address(this).balance >= amount, "insufficient treasury");
        used[idemKey] = true;
        totalPaid += amount;
        (bool ok,) = to.call{ value: amount }("");
        require(ok, "transfer failed");
    }
}

